      <DateInput.Root value={value} onValueChange={(e) => setValue(e.value)}>
        <DateInput.Label>Date of birth</DateInput.Label>
        <DateInput.Control>
          <DateInput.Segments />
        </DateInput.Control>
        <DateInput.HiddenInput />
      </DateInput.Root>
